// Workflow benchmarks for `view` — see docs/performance.md.
//
// Measures representative user workflows against realistic corpora
// (generated by scripts/make-corpus.swift): browser listing, recursive
// discovery, catalog interaction, scroll/prefetch scheduling, and
// thumbnail decoding. Each name describes a user-facing wait, not a
// micro-loop. Numbers are printed as JSON lines so they can be
// compared by redirecting stdout:
//
//   swift run -c release ViewBenchmarks -- \
//     --browser-corpus .work/corpus-2k --recursive-corpus .work/corpus-20k
//
// Supply corpus roots generated by scripts/make-corpus.swift. Fixture
// generation is never inside a timed region.

import CoreGraphics
import Darwin
import Foundation
import ImageIO
import viewCore

struct BenchResult: Encodable {
  let name: String
  let scale: String
  let samples: Int
  let medianMs: Double
  let p95Ms: Double
  let minMs: Double
  let maxMs: Double
  let rssBeforeKiB: Int64
  let rssAfterKiB: Int64
  let rssDeltaKiB: Int64
}

enum BenchError: Error, LocalizedError {
  case usage
  var errorDescription: String? {
    switch self {
    case .usage:
      "usage: ViewBenchmarks [--browser-corpus <path>] [--recursive-corpus <path>] [--samples <n>]"
    }
  }
}

var samples = 5
var browserCorpus: URL?
var recursiveCorpus: URL?

do {
  var args = CommandLine.arguments.dropFirst()
  while let arg = args.popFirst() {
    switch arg {
    case "--browser-corpus":
      guard let value = args.popFirst() else { throw BenchError.usage }
      browserCorpus = URL(filePath: value)
    case "--recursive-corpus":
      guard let value = args.popFirst() else { throw BenchError.usage }
      recursiveCorpus = URL(filePath: value)
    case "--samples":
      guard let value = args.popFirst(), let int = Int(value), int >= 1 else { throw BenchError.usage }
      samples = int
    default:
      throw BenchError.usage
    }
  }
} catch {
  FileHandle.standardError.write(Data("\(error.localizedDescription)\n".utf8))
  exit(1)
}

@discardableResult
func blackBox<T>(_ value: T) -> T { value }

actor ScanCounter {
  private(set) var count = 0
  func add(_ batch: Int) { count += batch }
}

func rssKiB() -> Int64 {
  var usage = rusage()
  let result = getrusage(RUSAGE_SELF, &usage)
  guard result == 0 else { return 0 }
  // ru_maxrss is bytes on macOS.
  return Int64(usage.ru_maxrss / 1024)
}

func median(_ values: [Double]) -> Double {
  let sorted = values.sorted()
  let middle = sorted.count / 2
  if sorted.count % 2 == 1 {
    return sorted[middle]
  }
  return (sorted[middle - 1] + sorted[middle]) / 2
}

func percentile(_ values: [Double], _ percentile: Double) -> Double {
  let sorted = values.sorted()
  let index = Int(ceil(percentile * Double(sorted.count))) - 1
  return sorted[min(max(index, 0), sorted.count - 1)]
}

func emit(_ result: BenchResult) {
  let data = try! JSONEncoder().encode(result)
  FileHandle.standardOutput.write(data)
  FileHandle.standardOutput.write(Data("\n".utf8))
}

func measure(
  name: String,
  scale: String,
  samples: Int,
  operation: (Int) async throws -> Void
) async {
  var times: [Double] = []
  times.reserveCapacity(samples)
  let rssBefore = rssKiB()
  for sample in 0..<samples {
    let start = ContinuousClock.now
    try? await operation(sample)
    let end = ContinuousClock.now
    let components = start.duration(to: end).components
    let elapsed = Double(components.seconds) * 1000 + Double(components.attoseconds) / 1_000_000_000_000_000
    times.append(elapsed)
  }
  let rssAfter = rssKiB()
  emit(BenchResult(
    name: name,
    scale: scale,
    samples: samples,
    medianMs: median(times),
    p95Ms: percentile(times, 0.95),
    minMs: times.min() ?? 0,
    maxMs: times.max() ?? 0,
    rssBeforeKiB: rssBefore,
    rssAfterKiB: rssAfter,
    rssDeltaKiB: rssAfter - rssBefore
  ))
}

func resolve(_ url: URL?) -> RootDirectory? {
  guard let url else { return nil }
  let candidate = URL(filePath: url.path).standardizedFileURL
  return try? RootDirectory.resolve(argument: candidate.path, currentDirectory: "/")
}

func imageFiles(under root: URL, limit: Int) -> [URL] {
  var found: [URL] = []
  var pending: [URL] = [root]
  while let current = pending.popLast(), found.count < limit {
    if let enumerator = FileManager.default.enumerator(at: current, includingPropertiesForKeys: nil) {
      for case let file as URL in enumerator {
        if file.pathExtension.lowercased() == "png" {
          found.append(file)
          if found.count >= limit { break }
        }
      }
    }
  }
  return found
}

func makeImage() -> CGImage {
  let context = CGContext(
    data: nil,
    width: 1,
    height: 1,
    bitsPerComponent: 8,
    bytesPerRow: 4,
    space: CGColorSpaceCreateDeviceRGB(),
    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
  )!
  return context.makeImage()!
}

func decodeOne(_ url: URL) {
  guard let source = CGImageSourceCreateWithURL(url as CFURL, nil) else { return }
  _ = CGImageSourceCreateImageAtIndex(source, 0, nil)
}

// Warm caches before timing and discard warm pass for I/O stability.
func warm(_ count: Int, operation: (Int) async throws -> Void) async {
  var warmed = 0
  while warmed < count {
    try? await operation(warmed)
    warmed += 1
  }
}

let benchStart = ContinuousClock.now

if let browser = resolve(browserCorpus) {
  // Representative browser workflow: listing one directory and materializing
  // the catalog, including the size/name sort users observe on open.
  await measure(name: "browser-list", scale: "\(browser.url.lastPathComponent)", samples: samples) { _ in
    var catalog = Catalog()
    let entries = try await DirectoryLister.list(directory: browser.url)
    _ = catalog.append(entries)
    blackBox(catalog.count)
  }
  await measure(name: "catalog-interact", scale: "5000", samples: samples) { sample in
    var catalog = Catalog()
    let items = (0..<5000).map { i in
      MediaItem(
        url: URL(filePath: "/bench/item-\(i).png"),
        kind: .image,
        modificationDate: Date(timeIntervalSince1970: TimeInterval(i)),
        fileSize: Int64((i * 137) % 400_000 + 1)
      )
    }
    _ = catalog.append(items)
    // Arrow-like moves, range select, remove/insert round-trip.
    for i in (0..<200).map({ $0 * 25 + sample % 25 }) {
      if let item = catalog.item(at: i) {
        try? catalog.select(item.url)
      }
    }
    let rangeStart = catalog.item(at: 100)?.url
    if let anchor = rangeStart, let target = catalog.item(at: 700)?.url {
      try? catalog.selectRange(anchor: anchor, clicked: target)
    }
    _ = catalog.remove(items[2500].url)
    _ = catalog.insert(items[2500], at: 2500)
    blackBox(catalog.selectedURL?.path)
  }
}

if let recursive = resolve(recursiveCorpus) {
  await measure(name: "recursive-scan", scale: "\(recursive.url.lastPathComponent)", samples: samples) { _ in
    let counter = ScanCounter()
    let summary = try await DirectoryScanner.scan(root: recursive) { batch in
      await counter.add(batch.count)
    }
    blackBox(summary.itemCount)
    blackBox(await counter.count)
  }
  // Deterministic scroll: sliding viewport over the corpus indexes.
  await measure(name: "scroll-prefetch", scale: "\(recursive.url.lastPathComponent)", samples: samples) { sample in
    let keys = imageFiles(under: recursive.url, limit: 2000).map { file in
      ThumbnailKey(item: MediaItem(url: file, kind: .image, modificationDate: nil, fileSize: nil), pixelSize: 320, scale: 2)!
    }
    guard keys.count >= 80 else { return }
    let scheduler = await MainActor.run {
      ThumbnailScheduler(
        volume: .local,
        cache: ThumbnailCache(),
        request: { key, _ in
          decodeOne(key.url)
          return makeImage()
        },
        resultSink: { _, _, _ in }
      )
    }
    let viewport = 24
    let prefetch = 48
    for offset in stride(from: 0, to: keys.count - viewport, by: 8) {
      let visible = Array(keys[offset..<(offset + viewport)])
      let next = Array(keys[(offset + viewport)..<min(keys.count, offset + viewport + prefetch)])
      await MainActor.run { scheduler.updateDemand(visible: visible, prefetch: next) }
    }
    await scheduler.cancelAll()
    blackBox(sample)
  }
  // Thumbnail decode over a realistic subset (varied PNG sizes in corpus).
  if let target = imageFiles(under: recursive.url, limit: 400).first {
    await measure(name: "thumb-decode", scale: "\(target.lastPathComponent)", samples: samples) { _ in
      let files = imageFiles(under: recursive.url, limit: 100)
      let start = ContinuousClock.now
      for file in files {
        decodeOne(file)
      }
      _ = start.duration(to: .now)
    }
  }
}

let totalMs = Double(benchStart.duration(to: .now).components.seconds) * 1000
FileHandle.standardError.write(Data("bench total-ms=\(Int(totalMs))\n".utf8))
